def transform(grid):
    bg = max(set(v for row in grid for v in row), key=lambda x: sum(row.count(x) for row in grid))
    out = [row[:] for row in grid]
    for i, row in enumerate(out):
        if any(v != bg for v in row):
            out[i] = [bg] * len(row)
            break
    return out
